const decodeUriComponent = require('decode-uri-component').default;
const decodeComponent = input => {
	const value = input.replace(/\+/g, ' ');
	try {
		return decodeURIComponent(value);
	} catch {
		if (value.length > 65536) {
			throw new URIError('Malformed query component exceeds the 65536 character fallback limit');
		}
		return decodeUriComponent(value);
	}
};
